package com.archos.mediacenter.video.utils;

import android.app.Application;
import android.content.Context;
import com.archos.mediaprovider.video.VideoOpenHelper;
import com.archos.mediacenter.video.utils.backup.*;
import java.io.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(application=Application.class,sdk=28) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public class CombinedPlaylistMediaTest {
    private Context app;
    @Before public void setup(){app=RuntimeEnvironment.getApplication();app.deleteDatabase("media.db");try(VideoOpenHelper helper=new VideoOpenHelper(app)){var db=helper.getWritableDatabase();db.execSQL("INSERT INTO files(_id,remote_id,media_type,_data,Archos_hiddenByUser,bookmark) VALUES(10,10,3,'file:///PRIVATE.mkv',1,4444)");db.execSQL("INSERT INTO MOVIE(_id,video_id,m_online_id,Nova_pinned,name_movie) VALUES(100,10,123,9,'PRIVATE_TITLE')");db.execSQL("INSERT INTO list_table(_id,title,trakt_id,sync_status) VALUES(7,'Original local',NULL,1),(9,'Receiving remote',987654,0)");db.execSQL("INSERT INTO video_list_table(_id,list_id,m_online_id,e_online_id,sync_status) VALUES(12,7,123,-1,1),(13,9,-1,456,0)");}}
    private JSONObject payload()throws Exception{return new JSONObject().put("schema",1).put("rows",new JSONArray().put(new JSONObject().put("id","playlist:12345678-1234-1234-1234-123456789012:1").put("name","Restored local").put("members",new JSONArray().put("tmdb:movie:321"))));}
    private JSONObject after(JSONObject before)throws Exception{JSONObject result=MediaStateRecovery.playlistAfter(before,PlaylistStateRecovery.prepare(before.getJSONObject("playlists"),payload(),before.getBoolean("exists")));if(!result.isNull("pins"))result.getJSONArray("pins").getJSONObject(0).put("value",400);if(!result.isNull("hidden"))result.getJSONArray("hidden").getJSONObject(0).put("value",false);MediaStateRecovery.validatePair(before,result);return result;}
    @Test public void sameMediaSqliteTransactionStagesPinsHiddenAndPlaylistsWithAtomicRollback()throws Exception{JSONObject before=MediaStateRecovery.capture(app,true,true,true),after=after(before);assertEquals(2,before.getInt("schema"));try(var session=MediaStateRecovery.begin(app,before,false)){session.write(after,()->false);}assertEquals(before.toString(),MediaStateRecovery.capture(app,true,true,true).toString());}
    @Test public void committingOneParticipantPersistsAllSelectedColumnsAndUnownedProgress()throws Exception{JSONObject before=MediaStateRecovery.capture(app,true,true,true),after=after(before);try(var session=MediaStateRecovery.begin(app,before,false)){session.write(after,()->false);session.commit();}assertEquals(after.toString(),MediaStateRecovery.capture(app,true,true,true).toString());try(VideoOpenHelper helper=new VideoOpenHelper(app);var row=helper.getReadableDatabase().rawQuery("SELECT bookmark,_data FROM files WHERE _id=10",null)){assertTrue(row.moveToFirst());assertEquals(4444,row.getLong(0));assertEquals("file:///PRIVATE.mkv",row.getString(1));}}
    @Test public void durableRedoAcceptsNativeBeforeOrAfterAndKeepsRemoteListsExact()throws Exception{JSONObject before=MediaStateRecovery.capture(app,true,true,true),after=after(before);MediaStateRecovery.recover(app,before,after,true);assertEquals(after.toString(),MediaStateRecovery.capture(app,true,true,true).toString());MediaStateRecovery.recover(app,before,after,true);assertEquals(after.toString(),MediaStateRecovery.capture(app,true,true,true).toString());MediaStateRecovery.recover(app,before,after,false);assertEquals(before.toString(),MediaStateRecovery.capture(app,true,true,true).toString());}
    @Test public void independentlyChangedPlaylistStateIsNeverOverwrittenByStaleRecovery()throws Exception{JSONObject before=MediaStateRecovery.capture(app,true,true,true),after=after(before);try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("UPDATE list_table SET title='Later manual change' WHERE _id=7");}String current=MediaStateRecovery.capture(app,true,true,true).toString();try{MediaStateRecovery.recover(app,before,after,true);fail();}catch(IOException expected){}assertEquals(current,MediaStateRecovery.capture(app,true,true,true).toString());}
    @Test public void stalePreviewAndCorruptPrivatePairFailBeforeAnyMediaMutation()throws Exception{JSONObject before=MediaStateRecovery.capture(app,true,true,true),after=after(before);after.getJSONObject("playlists").getJSONArray("definitions").getJSONObject(0).put("trakt",999);try{MediaStateRecovery.validatePair(before,after);fail();}catch(JSONException expected){}assertEquals(before.toString(),MediaStateRecovery.capture(app,true,true,true).toString());try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("INSERT INTO list_table(title,sync_status) VALUES('Later local',1)");}String current=MediaStateRecovery.capture(app,true,true,true).toString();try(var ignored=MediaStateRecovery.begin(app,before,false)){fail();}catch(IOException expected){}assertEquals(current,MediaStateRecovery.capture(app,true,true,true).toString());}
    @Test public void playlistOnlyReplacementLeavesUnselectedPinsAndHiddenValuesUntouched()throws Exception{JSONObject before=MediaStateRecovery.capture(app,false,false,true),after=after(before);try(var session=MediaStateRecovery.begin(app,before,false)){session.write(after,()->false);session.commit();}JSONObject other=MediaStateRecovery.capture(app,true,true);assertEquals(1,other.getInt("schema"));assertEquals(9,other.getJSONArray("pins").getJSONObject(0).getLong("value"));assertTrue(other.getJSONArray("hidden").getJSONObject(0).getBoolean("value"));}
    @Test public void absentMediaStoreNeverCreatedByPendingPlaylistPreparationOrRecovery()throws Exception{app.deleteDatabase("media.db");JSONObject before=MediaStateRecovery.capture(app,false,false,true);var prepared=PlaylistStateRecovery.prepare(before.getJSONObject("playlists"),payload(),false);JSONObject after=MediaStateRecovery.playlistAfter(before,prepared);assertEquals(1,prepared.unresolved);MediaStateRecovery.recover(app,before,after,true);assertFalse(VideoOpenHelper.getDatabaseFile(app).exists());}
}
